import { readFile, writeFile } from "node:fs/promises";

const assetNames = ["Dockerfile", "controller.py", "launcher.py", "start.sh"];
const sourceDirectory = new URL("../src/controller/", import.meta.url);
const output = new URL(
  "../src/controller-assets.generated.ts",
  import.meta.url,
);

const entries = await Promise.all(
  assetNames.map(async (name) => {
    const bytes = await readFile(new URL(name, sourceDirectory));
    return `  ${JSON.stringify(name)}: ${JSON.stringify(bytes.toString("base64"))},`;
  }),
);

await writeFile(
  output,
  [
    "// Generated by scripts/generate-controller-assets.mjs. Do not edit.",
    "export const CONTROLLER_ASSETS = {",
    ...entries,
    "} as const;",
    "",
  ].join("\n"),
);
